# Inventors Ladder: Modern Explainers (course key invmodern). Helpers come from scripts/inventors/build.py.
# Hawking's and Sagan's books are under copyright: our own summaries and reading guides only, at most a few words quoted,
# with library links (Open Library, WorldCat), like the Great Books Ladder's nopd rungs. Chapter titles checked against
# library catalogs (proofwiki contents list for The Universe in a Nutshell; catalog contents for Cosmos).

def TB3(head, lab, rows, cap):
    """A three-part reading guide shown as two columns (narrow screens): the third part goes under the summary."""
    return TB(head, [(a, '%s<br><i>%s:</i> %s' % (b, lab, c)) for a, b, c in rows], cap)

